#!/usr/bin/env python3
"""Regression tests: docs/INCIDENTS.md must be regenerated by the same pre-push and
merge-queue regeneration path as tools/INDEX.md, so a lane whose branch carries an
Incident-Class trailer can push a fresh file and the incident-report-gate stays
consistent between a PR and main.

Defect (2026-10-15, PRs #1014/#1020/#1025): `incident_report.py --check` scans HEAD's
history (since #1008), so every PR that carries an incident-classified commit drifts the
committed docs/INCIDENTS.md. Nothing regenerated that file: it was absent from
`generated_paths.REGISTRY`, `merge_queue.REGENERATORS` and `tools/regen_all.py`, so
`regen_all --check` never saw it and the lane could not repair it.

Hermetic: every fixture is a throwaway temp git repo with its own copies of
`tools/incident_report.py`, `tools/subprocess_common.py` and `tools/regen_all.py`;
identity is forced per invocation; the cwd is never changed.
"""

import shutil
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[1]
TOOLS = REPO_ROOT / "tools"
REGEN_ALL = TOOLS / "regen_all.py"
INCIDENT_REPORT = TOOLS / "incident_report.py"
SUBPROCESS_COMMON = TOOLS / "subprocess_common.py"
GEN_TOOL_INDEX = TOOLS / "gen_tool_index.py"
TARGET = "docs/INCIDENTS.md"


def _py(argv, cwd):
    return subprocess.run(
        [sys.executable] + [str(a) for a in argv],
        cwd=str(cwd), capture_output=True, text=True,
        encoding="utf-8", errors="replace", timeout=180)


def _git(args, cwd):
    return subprocess.run(
        ["git", "-c", "user.email=t@example.invalid", "-c", "user.name=t",
         "-c", "commit.gpgsign=false"] + args,
        cwd=str(cwd), capture_output=True, text=True,
        encoding="utf-8", errors="replace", timeout=120)


class IncidentRegenFixture(unittest.TestCase):
    """Throwaway repo on main with a committed, freshly generated docs/INCIDENTS.md."""

    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory(prefix="aesop-incregen-")
        self.root = Path(self._tmp.name)
        self.addCleanup(self._tmp.cleanup)

        (self.root / "tools").mkdir()
        (self.root / "docs").mkdir()
        shutil.copyfile(str(INCIDENT_REPORT), str(self.root / "tools" / "incident_report.py"))
        shutil.copyfile(str(SUBPROCESS_COMMON), str(self.root / "tools" / "subprocess_common.py"))
        
        # regen_all runs every merge_queue.REGENERATORS entry, so the INDEX generator must exist too.
        shutil.copyfile(str(GEN_TOOL_INDEX), str(self.root / "tools" / "gen_tool_index.py"))

        self.git("init", "-q", "-b", "main")
        (self.root / "app.txt").write_text("v1\n", encoding="utf-8", newline="\n")
        self.git("add", "-A")
        self.git("commit", "-q", "-m", "feat: initial app")
        self.regenerate_and_commit("docs: regenerate incident log")

    def git(self, *args):
        proc = _git(list(args), self.root)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        return proc.stdout

    def regenerate_and_commit(self, subject):
        proc = _py(["tools/incident_report.py", "--regenerate", "--repo", "."], self.root)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.git("add", "-A")
        self.git("commit", "-q", "-m", subject)

    def check(self):
        return _py(["tools/incident_report.py", "--check", "--repo", "."], self.root)

    def commit_incident_on_branch(self):
        self.git("checkout", "-q", "-b", "lane/incident")
        (self.root / "app.txt").write_text("v2\n", encoding="utf-8", newline="\n")
        self.git("add", "-A")
        self.git("commit", "-q", "-m", "feat: lane change",
                 "-m", "Incident-Class: gate-activation")


class RegistrationTests(unittest.TestCase):
    """The committed file is a registered, regenerable artifact."""

    def test_incidents_is_registered_with_regenerator(self):
        sys.path.insert(0, str(TOOLS))
        try:
            import generated_paths
            import merge_queue
        finally:
            sys.path.pop(0)
        self.assertIsNotNone(generated_paths.is_generated(TARGET))
        self.assertEqual(generated_paths.regenerator_for(TARGET),
                         ["tools/incident_report.py", "--regenerate"])
        self.assertIn(("tools/incident_report.py", "--regenerate"),
                      set(merge_queue.REGENERATORS))


class MainStaysGreenTests(IncidentRegenFixture):
    def test_main_fixture_is_green(self):
        proc = self.check()
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)


class LaneRegenerationTests(IncidentRegenFixture):
    def test_trailer_commit_goes_red_and_regen_all_repairs_it(self):
        self.commit_incident_on_branch()

        stale = self.check()
        self.assertEqual(stale.returncode, 1, "trailer commit must drift the committed file")
        self.assertIn("DRIFT", stale.stdout)

        drift = _py([REGEN_ALL, "--check", "--repo", "."], self.root)
        self.assertEqual(drift.returncode, 1, drift.stdout + drift.stderr)
        self.assertIn(TARGET, drift.stdout + drift.stderr)

        fix = _py([REGEN_ALL, "--fix", "--repo", "."], self.root)
        self.assertEqual(fix.returncode, 0, fix.stdout + fix.stderr)
        self.assertIn(TARGET, self.git("status", "--porcelain"))

        self.git("add", "-A")
        self.git("commit", "-q", "-m", "docs(incidents): regenerate incident log")
        green = self.check()
        self.assertEqual(green.returncode, 0, green.stdout + green.stderr)

    def test_regen_all_check_is_clean_when_file_is_fresh(self):
        proc = _py([REGEN_ALL, "--check", "--repo", "."], self.root)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)


class ShallowAndStdoutTests(IncidentRegenFixture):
    def test_stdout_matches_committed_bytes_for_fresh_file(self):
        proc = _py(["tools/incident_report.py", "--stdout", "--repo", "."], self.root)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        committed = (self.root / TARGET).read_text(encoding="utf-8")
        self.assertEqual(proc.stdout.replace("\r\n", "\n"), committed.replace("\r\n", "\n"))

    def test_regenerate_refuses_shallow_clone_and_writes_nothing(self):
        clone = self.root.parent / (self.root.name + "-shallow")
        self.addCleanup(lambda: shutil.rmtree(str(clone), ignore_errors=True))
        proc = subprocess.run(
            ["git", "clone", "-q", "--depth", "1", "--no-local",
             "file://" + str(self.root).replace("\\", "/"), str(clone)],
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=120)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        before = (clone / TARGET).read_bytes()
        regen = _py(["tools/incident_report.py", "--regenerate", "--repo", "."], clone)
        self.assertEqual(regen.returncode, 2, regen.stdout + regen.stderr)
        self.assertIn("shallow", regen.stderr)
        self.assertEqual((clone / TARGET).read_bytes(), before)


if __name__ == "__main__":
    unittest.main()
